mapper.sql:
event_type = 'MODEL_CALL_RECORDED' AND actor_user_id IS NULL
AND details->>'schemaVersion' = '1'
AND occurred_at >= #{period.fromInclusive} AND occurred_at < #{period.toExclusive}
AND tenant_id = #{tenantId}

mapper.select:
, eligible AS ( SELECT *,
provider_route || ' / ' || model operation AS source FROM calls WHERE NOT mock AND transport_state NOT IN ('NOT_SENT', 'MOCK') ) SELECT source, COUNT(*) AS call_count, COUNT(*) FILTER (WHERE successful) AS success_count, COUNT(*) FILTER (WHERE NOT successful) AS failure_count, COUNT(*) FILTER (WHERE usage_state = 'COMPLETE') AS complete_usage_count, COUNT(*) FILTER (WHERE usage_state = 'PARTIAL') AS partial_usage_count, COUNT(*) FILTER (WHERE usage_state = 'UNKNOWN') AS unknown_usage_count, COUNT(*) FILTER (WHERE usage_state = 'INVALID') AS invalid_usage_count,
COALESCE(SUM(input_tokens) FILTER (WHERE usage_state != 'INVALID'), 0)::text AS input_tokens, COALESCE(SUM(output_tokens) FILTER (WHERE usage_state != 'INVALID'), 0)::text AS output_tokens, COALESCE(SUM(total_tokens) FILTER (WHERE usage_state != 'INVALID'), 0)::text AS total_tokens, COALESCE(SUM(cache_hit_tokens) FILTER (WHERE usage_state != 'INVALID'), 0)::text AS cache_hit_tokens, COALESCE(SUM(cache_miss_tokens) FILTER (WHERE usage_state != 'INVALID'), 0)::text AS cache_miss_tokens FROM eligible GROUP BY source ORDER BY COALESCE(SUM(total_tokens) FILTER (WHERE usage_state != 'INVALID'), 0) DESC, COUNT(*) DESC, source LIMIT #{limit}
